mapper.update:
UPDATE etf_product
SET current_price = #{currentPrice}
WHERE etf_code = #{etfCode}

mapper.select:
SELECT etf_id, etf_code, etf_name, market, theme, risk_rating, aum, fee, current_price, return_1mo, return_3mo, return_6mo, return_1yr, return_3yr, created_at FROM etf_product WHERE 1 = 1
AND (etf_name LIKE CONCAT('%', #{keyword}, '%') OR etf_code LIKE CONCAT('%', #{keyword}, '%'))
AND market = #{market}
AND theme = #{theme}
AND fee >= #{minFee}
AND fee <= #{maxFee}
AND aum >= #{minAum}
AND aum <= #{maxAum}
AND risk_rating = #{riskRating}
ORDER BY
fee return_1yr aum risk_rating aum
ASC DESC
ORDER BY aum DESC

